mapper.update:
CREATE INDEX ${tableName}_IDX1 ON ${tableName} (TR_SENDSTAT, TR_SENDDATE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (TR_PHONE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (TR_RSLTSTAT, TR_SENDDATE);

UPDATE ${tableName}
SET
    TR_SENDSTAT = CASE WHEN TR_SENDSTAT = '2' THEN TR_SENDSTAT ELSE #{parameter.messageStatus} END,
    TR_MODIFIED = NOW()
    , TR_REALSENDDATE = FROM_UNIXTIME(UNIX_TIMESTAMP(#{parameter.sentDate}))
    , TR_ROUTEID = #{parameter.routeId}
    , TR_RSLTSTAT = #{parameter.doneCode}
    , TR_RSLTDATE = FROM_UNIXTIME(UNIX_TIMESTAMP(#{parameter.doneDate}))
    , TR_NET = #{parameter.doneTelco}
WHERE
    TR_NUM IS NULL
    TR_NUM = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    TR_NUM IS NULL
    TR_NUM = #{parameter.key}
